/**
 * Observed history from real collection instants, plus a projected horizon and the obligation deadlines that fall in it. Observed points come only from instants at which a collection actually happened — the series is never resampled onto a regular grid, because that would draw a smooth trend on an estate that never changed. When fewer than two distinct instants exist, `observed.sufficientForTrend` is false and `reason` says so.

 * @summary Estate cryptographic posture over time (D7)
 */
export const GetInventoryTimelineResponse = zod.object({
  generatedAt: zod.coerce.date(),
  now: zod.coerce.date(),
  framing: zod
    .string()
    .describe(
      "Mandatory wherever a scenario year is shown — a Q-Day year is a scenario, not a forecast.",
    ),
  scenarios: zod.array(
    zod.object({
      name: zod.string(),
      qDayYear: zod.number(),
      rationale: zod.string(),
      confidence: zod.string(),
    }),
  ),
  estate: zod.object({
    projects: zod.array(
      zod.object({
        id: zod.number(),
        name: zod.string(),
        assets: zod.number(),
        presentAssets: zod.number(),
      }),
    ),
    unassociatedAssets: zod
      .number()
      .describe(
        "Assets whose location carries no project prefix. Surfaces such as tls\/certificate have no project.",
      ),
    totalAssets: zod.number(),
    presentAssets: zod.number(),
  }),
  certificateExpiry: zod
    .object({
      certificates: zod
        .number()
        .describe(
          "Non-retired assets on the `certificate` surface. The denominator.",
        ),
      withKnownExpiry: zod
        .number()
        .describe("Of those, how many state a `notAfter` this could read."),
      undetermined: zod
        .number()
        .describe(
          "Of those, how many do not. Counted rather than dropped — a certificate we cannot date is not a certificate that expires safely.",
        ),
      perScenario: zod.array(
        zod.object({
          scenario: zod.string(),
          qDayYear: zod.number(),
          outlivesQDay: zod
            .number()
            .describe(
              "Certificates still valid on 1 January of `qDayYear` — the finding that matters.",
            ),
          expiresBeforeQDay: zod
            .number()
            .describe(
              "Certificates replaced on their own renewal cycle before that date.",
            ),
          undetermined: zod
            .number()
            .describe(
              "Repeated per scenario so a count is never read without knowing what it excludes.",
            ),
        }),
      ),
      caveat: zod.string().describe("Shown on the page, not in a tooltip."),
    })
    .describe(
      "G-22 \/ doc 06 Row 5 — how many certificates the estate currently holds are still valid on each Q-Day scenario. A narrow question that needs no assumption: will the trust anchored in this certificate's public-key algorithm still be in force on the day the certificate itself says it expires? This is not Mosca (`X + Y > Z`) — a certificate has no secrecy lifetime of its own.\n\n\*\*Three buckets, and the third is the point.\*\* A certificate whose `notAfter` is missing, sits on a non-certificate detail, or does not parse is `undetermined` — never folded into `expiresBeforeQDay`, which is the reassuring answer. Retired (`gone`) certificates are excluded, so this describes the estate as it is rather than everything it ever held.",
    ),
  observed: zod.object({
    sufficientForTrend: zod
      .boolean()
      .describe(
        "False when fewer than two distinct collection instants exist. The client must draw no line.",
      ),
    reason: zod.string(),
    distinctCollectionInstants: zod.number(),
    observedSpanDays: zod.number().nullable(),
    firstObservedAt: zod.coerce.date().nullable(),
    lastObservedAt: zod.coerce.date().nullable(),
    completedRuns: zod.number(),
    failedRuns: zod
      .number()
      .describe(
        "A failed run places no point on the axis; it is reported here instead.",
      ),
    points: zod.array(
      zod
        .object({
          at: zod.coerce
            .date()
            .describe(
              "For an observed point this is a real collection_runs timestamp, not a grid tick.",
            ),
          assetsKnown: zod.number(),
          assetsPresent: zod
            .number()
            .describe(
              "Assets present and not yet gone at this instant. The number the verdicts are over.",
            ),
          pqcAssets: zod.number(),
          hygieneAssets: zod.number(),
          unmappedAssets: zod.number(),
          breachedByScenario: zod
            .record(zod.string(), zod.number())
            .describe(
              "Assets breaching Mosca at this instant, one count per Q-Day scenario.",
            ),
        })
        .and(
          zod.object({
            kind: zod.enum(["observed"]),
            collectionRunIds: zod.array(zod.number()),
            surfaces: zod.array(zod.string()),
            assetsAdded: zod.number(),
          }),
        ),
    ),
  }),
  projected: zod.object({
    assumption: zod
      .string()
      .describe(
        "What is held constant. Projections move because Z shrinks, not because the estate changed.",
      ),
    basisAt: zod.coerce.date(),
    points: zod.array(
      zod
        .object({
          at: zod.coerce
            .date()
            .describe(
              "For an observed point this is a real collection_runs timestamp, not a grid tick.",
            ),
          assetsKnown: zod.number(),
          assetsPresent: zod
            .number()
            .describe(
              "Assets present and not yet gone at this instant. The number the verdicts are over.",
            ),
          pqcAssets: zod.number(),
          hygieneAssets: zod.number(),
          unmappedAssets: zod.number(),
          breachedByScenario: zod
            .record(zod.string(), zod.number())
            .describe(
              "Assets breaching Mosca at this instant, one count per Q-Day scenario.",
            ),
        })
        .and(
          zod.object({
            kind: zod.enum(["projected"]),
            year: zod.number(),
          }),
        ),
    ),
  }),
  deadlines: zod.array(
    zod.object({
      id: zod
        .string()
        .describe(
          "Keyed on framework + type + effective date + appliesTo + securityStrength.",
        ),
      type: zod.string(),
      label: zod.string(),
      effect: zod.string(),
      effectiveFrom: zod.string(),
      year: zod.number(),
      inEffect: zod.boolean(),
      appliesTo: zod.string().nullable(),
      securityStrength: zod.string().nullable(),
      framework: zod.string(),
      frameworkName: zod.string().nullable(),
      requirement: zod.string(),
      citation: zod
        .object({
          document: zod.string(),
          section: zod.string().optional(),
          url: zod.string(),
          retrievedAt: zod.string().optional(),
          published: zod.string().optional(),
        })
        .describe(
          "Provenance for a single regulatory claim. Required on every obligation.",
        ),
      confidence: zod.string(),
      draftStatus: zod.string().nullable(),
      algorithms: zod.array(zod.string()),
      assets: zod.number(),
      caveats: zod.array(zod.string()),
    }),
  ),
  inputs: zod.object({
    secrecyLifetime: zod.object({
      bySource: zod.record(zod.string(), zod.number()),
      assumedForAssets: zod.number(),
      bases: zod.array(zod.string()),
    }),
    migrationYears: zod.object({
      defaultValue: zod.number(),
      assetsWithRecordedEffort: zod.number(),
      basis: zod
        .string()
        .describe(
          "States plainly that Y is not measured yet, so a reader knows X vs Z decided the verdict.",
        ),
    }),
  }),
  notCollected: zod
    .array(
      zod.object({
        id: zod.string(),
        label: zod.string(),
        reason: zod.string(),
      }),
    )
    .describe(
      "Facts a reader expects on a time-pressure panel that this product cannot produce, stated rather than omitted.",
    ),
});

/**
 * Five sections tracking the named parts of the joint CISA/NSA/NIST quantum-readiness factsheet (August 2023), plus the estate-wide coverage meter the first section is defined against — bundled in one payload so the two cannot disagree. A section with no data source in this product (roadmap document attachment, the vendor register) reports `percentComplete: null` and `state: "not-tracked"`, never `0`. There is no combined/overall readiness score.
 * @summary CISA quantum-readiness posture tracker (D1)
 */
export const GetInventoryReadinessResponse = zod
  .object({
    generatedAt: zod.coerce.date(),
    framing: zod
      .string()
      .describe(
        "States the factsheet's name and date. The factsheet is organised into named sections, not a numbered stage sequence — this must never read as a CISA-authored numbering.",
      ),
    sections: zod.array(
      zod
        .object({
          id: zod.enum([
            "roadmap",
            "cryptographic-inventory",
            "prioritisation",
            "vendor-engagement",
            "supply-chain",
          ]),
          label: zod.string(),
          definition: zod
            .string()
            .describe(
              'What \"complete\" means for this section, stated plainly rather than left implicit.',
            ),
          state: zod.enum(["tracked", "not-tracked"]),
          percentComplete: zod.number().nullable(),
          numerator: zod.number().nullable(),
          denominator: zod.number().nullable(),
          reason: zod.string(),
        })
        .describe(
          'One named part of the CISA\/NSA\/NIST factsheet. `state: \"not-tracked\"` means this product has no data source for the section at all (e.g. no roadmap-document attachment, no vendor register) — `percentComplete` is null in that case, never 0, because 0 would assert a measurement nobody took.',
        ),
    ),
    coverage: zod
      .object({
        examinedSurfaces: zod.number(),
        totalSurfaces: zod.number(),
        surfaces: zod.array(
          zod.object({
            surface: zod
              .string()
              .describe(
                "The `Surface` enum value, i.e. how the database records it.",
              ),
            surfaceId: zod
              .string()
              .nullable()
              .describe(
                "The collector catalogue id, so a caller can join presentation without re-deriving the mapping. Null for a surface with no catalogue entry.",
              ),
            state: zod
              .enum(["examined", "examined-nothing-found", "never-examined"])
              .describe(
                "`examined-nothing-found` is its own state on purpose: a clean result and an absent one are different facts, and collapsing them loses the only one a reader cares about when the answer is zero.",
              ),
            completedRuns: zod.number(),
            failedRuns: zod
              .number()
              .describe(
                "A failed run is an attempt, not an examination. It is counted here and kept out of `completedRuns` so it can never make a surface look examined.",
              ),
            lastExaminedAt: zod.coerce.date().nullable(),
            assets: zod.number(),
            activeAssets: zod.number(),
          }),
        ),
        confidence: zod.object({
          basis: zod
            .enum(["latest observation per active asset"])
            .describe(
              "Stated in the payload so a report built from it can quote the basis rather than guess it. One point per asset, not per observation — weighting by scan frequency would describe our scheduling, not our evidence quality.",
            ),
          scored: zod.number(),
          unscored: zod
            .number()
            .describe(
              "Active assets with no observation at all. Non-zero means a data problem, and hiding it would be the wrong default.",
            ),
          excludedByAssetStatus: zod
            .record(zod.string(), zod.number())
            .describe(
              "Assets deliberately left out of the distribution, keyed by asset status.",
            ),
          distinctValues: zod.number(),
          min: zod.number().nullable(),
          max: zod.number().nullable(),
          mean: zod.number().nullable(),
          buckets: zod.array(
            zod
              .object({
                label: zod.string(),
                lower: zod.number(),
                upper: zod.number(),
                count: zod.number(),
              })
              .describe(
                "Half-open bucket, [lower, upper), except the last which includes 1.0.",
              ),
          ),
        }),
      })
      .describe(
        "The same shape and the same honesty rules as `ProjectCoverage` (D3's per-project meter), computed over the whole organisation instead of one project — reusing `summariseProjectCoverage` verbatim, since its output never depended on a project scope in the first place. No `projectId`: the whole point is that it is not one.",
      ),
  })
  .describe(
    "D1 Row 1 plus the estate coverage meter (Row 3) it is partly defined against, in one payload so the two cannot disagree. Deliberately carries no combined\/overall readiness score — averaging a measured section with an untracked one would invent a denominator, and that is the one number a buyer would screenshot and nobody could defend.",
  );

